def main() -> None:
    raw = base64.b64decode("".join(BUNDLE_B64.split()))
    actual = hashlib.sha256(raw).hexdigest()
    if actual != EXPECTED_SHA256:
        raise SystemExit("Embedded site bundle is corrupted.")
    out = Path("dist")
    if out.exists(): shutil.rmtree(out)
    out.mkdir(parents=True)
    with zipfile.ZipFile(io.BytesIO(raw)) as zf: zf.extractall(out)
    count = sum(1 for p in out.rglob("*") if p.is_file())
    print(f"Links site v{VERSION}: generated {count} files in {out.resolve()}")
if __name__ == "__main__": main()
